<?php
require_once __DIR__.'/inc/bootstrap.php';require_once __DIR__.'/inc/organizer_site.php';require_login();
$pdo=db();$user=current_user();if(!tickex_is_super_admin($user))abort_404('No tenés permiso.');tickex_organizer_site_ensure_schema($pdo);$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!tickex_csrf_verify(isset($_POST['_csrf'])?(string)$_POST['_csrf']:''))$error='La sesión venció. Actualizá la página.';
 else try{$siteId=isset($_POST['site_id'])?(int)$_POST['site_id']:0;$status=isset($_POST['domain_status'])?(string)$_POST['domain_status']:'not_configured';if(!in_array($status,array('not_configured','pending','verified','rejected'),true))throw new RuntimeException('Estado inválido.');$st=$pdo->prepare('SELECT custom_domain FROM clientes_sites WHERE id=:id');$st->execute(array(':id'=>$siteId));$domain=(string)$st->fetchColumn();if($siteId<=0||$domain==='')throw new RuntimeException('El sitio no tiene un dominio para revisar.');tickex_organizer_site_domain($domain);$white=$status==='verified'&&!empty($_POST['white_label_enabled'])?1:0;$st=$pdo->prepare('UPDATE clientes_sites SET custom_domain_status=:status,white_label_enabled=:white,updated_at=:updated WHERE id=:id');$st->execute(array(':status'=>$status,':white'=>$white,':updated'=>date('c'),':id'=>$siteId));flash('ok','Configuración pública actualizada.');header('Location: superadmin_sites.php');exit;}catch(Exception $e){$error=$e->getMessage();}
}
$q=isset($_GET['q'])?trim((string)$_GET['q']):'';$sql="SELECT s.*,a.email,a.nombre,a.apellido FROM clientes_sites s LEFT JOIN usuarios_admin a ON a.id=s.admin_id";$params=array();if($q!==''){$sql.=" WHERE lower(s.nombre_publico) LIKE :q OR lower(s.slug_publico) LIKE :q OR lower(COALESCE(s.custom_domain,'')) LIKE :q OR lower(COALESCE(a.email,'')) LIKE :q";$params[':q']='%'.strtolower($q).'%';}$sql.=" ORDER BY CASE s.custom_domain_status WHEN 'pending' THEN 0 ELSE 1 END,s.updated_at DESC,s.id DESC";$st=$pdo->prepare($sql);$st->execute($params);$sites=$st->fetchAll(PDO::FETCH_ASSOC);$csrf=tickex_csrf_token();$flashes=flash_get_all();$title='Sitios y dominios';include __DIR__.'/inc/layout_top.php';
?><style>.sites-page{max-width:1200px;margin:auto;display:grid;gap:16px}.sites-hero{padding:29px;background:radial-gradient(circle at 88% 5%,rgba(74,216,235,.15),transparent 30%),linear-gradient(135deg,#171b38,#35226e)}.sites-kicker{color:#5edbef;font-size:11px;font-weight:900;letter-spacing:.13em;text-transform:uppercase}.sites-hero h1{margin:7px 0;font-size:clamp(32px,5vw,48px)}.sites-hero p{margin:0;color:#c5c8d8}.sites-toolbar{display:flex;gap:9px}.sites-toolbar input{flex:1}.sites-list{display:grid;gap:10px}.site-row{display:grid;grid-template-columns:minmax(210px,1.15fr) minmax(190px,.9fr) minmax(170px,.7fr) auto;gap:14px;align-items:end;padding:16px;border:1px solid var(--line);border-radius:15px;background:rgba(255,255,255,.02)}.site-name strong,.site-name small{display:block}.site-name small{color:var(--muted)}.site-url{word-break:break-word}.site-row label{font-size:11px;color:var(--muted)}.site-row label select{margin-top:5px}.site-actions{display:flex;align-items:center;gap:8px}.state{display:inline-flex;margin-top:6px;padding:4px 8px;border:1px solid var(--line);border-radius:999px;font-size:10px;text-transform:uppercase;font-weight:850}.state.pending{color:#ffc36a}.state.verified{color:#58dfa4}.empty{text-align:center;color:var(--muted);padding:30px}@media(max-width:900px){.site-row{grid-template-columns:1fr 1fr}.site-actions{grid-column:1/-1}}@media(max-width:580px){.site-row{grid-template-columns:1fr}.site-actions{grid-column:auto;align-items:stretch;flex-direction:column}.sites-toolbar{display:grid}}</style><main class="sites-page"><section class="card sites-hero"><div class="sites-kicker">Presencia pública</div><h1>Sitios y dominios</h1><p>Revisá solicitudes de dominio y habilitá marca blanca solamente cuando DNS, certificado y plan estén confirmados.</p></section><?php foreach($flashes as $flash):?><div class="flash <?php echo e($flash['type']);?>"><?php echo e($flash['msg']);?></div><?php endforeach;?><?php if($error!==''):?><div class="flash err"><?php echo e($error);?></div><?php endif;?><section class="card"><form class="sites-toolbar" method="get"><input name="q" value="<?php echo e($q);?>" placeholder="Buscar productora, dominio o email"><button class="btn" type="submit">Buscar</button></form></section><section class="card"><div class="sites-list"><?php if(!$sites):?><div class="empty">No hay sitios configurados.</div><?php endif;?><?php foreach($sites as $site):?><form class="site-row" method="post"><input type="hidden" name="_csrf" value="<?php echo e($csrf);?>"><input type="hidden" name="site_id" value="<?php echo (int)$site['id'];?>"><div class="site-name"><strong><?php echo e($site['nombre_publico']);?></strong><small><?php echo e($site['email']);?> · <?php echo e($site['slug_publico']);?></small></div><div class="site-url"><label>Dominio solicitado</label><strong><?php echo e($site['custom_domain']?:'Sin dominio propio');?></strong><span class="state <?php echo e($site['custom_domain_status']);?>"><?php echo e($site['custom_domain_status']);?></span></div><label>Verificación<select name="domain_status"<?php echo empty($site['custom_domain'])?' disabled':'';?>><?php foreach(array('pending'=>'Pendiente','verified'=>'Verificado','rejected'=>'Rechazado','not_configured'=>'Sin configurar') as $key=>$label):?><option value="<?php echo e($key);?>"<?php echo $site['custom_domain_status']===$key?' selected':'';?>><?php echo e($label);?></option><?php endforeach;?></select></label><div class="site-actions"><label><input type="checkbox" name="white_label_enabled" value="1"<?php echo !empty($site['white_label_enabled'])?' checked':'';?><?php echo empty($site['custom_domain'])?' disabled':'';?>> Marca blanca</label><button class="btn secondary" type="submit"<?php echo empty($site['custom_domain'])?' disabled':'';?>>Actualizar</button></div></form><?php endforeach;?></div></section></main><?php include __DIR__.'/inc/layout_bottom.php';?>
